<?php
declare(strict_types=1);require dirname(__DIR__).'/lib/bootstrap.php';require dirname(__DIR__).'/lib/admin.php';require_admin();$pdo=db();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'save');if($action==='delete'){$pdo->prepare('DELETE FROM categories WHERE id=?')->execute([(int)$_POST['id']]);$msg='削除しました。';}else{$id=(int)($_POST['id']??0);$v=[trim((string)$_POST['name']),trim((string)$_POST['slug']),(int)($_POST['rakuten_genre_id']??0)?:null,trim((string)$_POST['keywords']),trim((string)$_POST['ng_keywords']),(int)($_POST['sort_order']??0),isset($_POST['is_active'])?1:0];if($id){$pdo->prepare('UPDATE categories SET name=?,slug=?,rakuten_genre_id=?,keywords=?,ng_keywords=?,sort_order=?,is_active=? WHERE id=?')->execute([...$v,$id]);}else{$pdo->prepare('INSERT INTO categories(name,slug,rakuten_genre_id,keywords,ng_keywords,sort_order,is_active) VALUES(?,?,?,?,?,?,?)')->execute($v);}$msg='保存しました。';}}$rows=$pdo->query('SELECT * FROM categories ORDER BY sort_order,id')->fetchAll();?><!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>カテゴリ管理</title><style>body{font-family:sans-serif;background:#f0f0f1;margin:0}main{max-width:1100px;margin:auto;padding:22px}.box{background:#fff;border:1px solid #dcdcde;padding:18px;margin-bottom:16px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}input,textarea{width:100%;padding:9px;box-sizing:border-box}button{padding:9px 14px}.row{border-top:1px solid #eee;padding:14px 0}</style></head><body><main><p><a href="index.php">← 管理トップ</a></p><h1>公開カテゴリ管理</h1><p>楽天Genre IDを内部で使い、公開側には分かりやすいカテゴリ名を表示します。</p><?php if($msg):?><p><?=h($msg)?></p><?php endif?><div class="box"><h2>新規カテゴリ</h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><div class="grid"><label>カテゴリ名<input name="name" required></label><label>スラッグ<input name="slug" required pattern="[a-z0-9-]+"></label><label>楽天Genre ID<input name="rakuten_genre_id" type="number"></label><label>表示順<input name="sort_order" type="number" value="0"></label></div><label>補助キーワード（1行1件）<textarea name="keywords"></textarea></label><label>NGキーワード<textarea name="ng_keywords"></textarea></label><label><input type="checkbox" name="is_active" checked> 公開</label><br><button>追加</button></form></div><?php foreach($rows as $r):?><div class="box row"><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><div class="grid"><label>カテゴリ名<input name="name" value="<?=h((string)$r['name'])?>"></label><label>スラッグ<input name="slug" value="<?=h((string)$r['slug'])?>"></label><label>楽天Genre ID<input name="rakuten_genre_id" value="<?=h((string)$r['rakuten_genre_id'])?>"></label><label>表示順<input name="sort_order" value="<?=(int)$r['sort_order']?>"></label></div><label>補助キーワード<textarea name="keywords"><?=h((string)$r['keywords'])?></textarea></label><label>NGキーワード<textarea name="ng_keywords"><?=h((string)$r['ng_keywords'])?></textarea></label><label><input type="checkbox" name="is_active" <?=$r['is_active']?'checked':''?>> 公開</label><p><button name="action" value="save">保存</button> <button name="action" value="delete" onclick="return confirm('本当に削除しますか？')">削除</button></p></form></div><?php endforeach?></main></body></html>
